package com.tradepilot.backtest.engine;
import com.tradepilot.backtest.model.*; import org.junit.jupiter.api.Test; import java.math.*; import java.time.*; import java.util.*; import static org.assertj.core.api.Assertions.*;
class IfvgAndDisplacementTests { private BacktestBar bar(int n,String o,String h,String l,String c){return new BacktestBar(Instant.parse("2026-09-08T14:"+String.format("%02d",n)+":00Z"),1,new BigDecimal(o),new BigDecimal(h),new BigDecimal(l),new BigDecimal(c),1);}
 @Test void bullishFvgInvertsOnlyAfterAClosingViolation(){PriceZone fvg=new PriceZone(PriceZone.Direction.BULLISH,new BigDecimal("100"),new BigDecimal("102"),bar(0,"100","101","99","100").time(),1,false);assertThat(new IfvgDetector().invert(fvg,bar(1,"101","102","98","99"),true,true)).hasValueSatisfying(z->{assertThat(z.direction()).isEqualTo(PriceZone.Direction.BEARISH);assertThat(z.confirmedAt()).isEqualTo(bar(1,"101","102","98","99").time());});}
 @Test void bearishFvgInvertsOnlyAfterAClosingViolation(){PriceZone fvg=new PriceZone(PriceZone.Direction.BEARISH,new BigDecimal("100"),new BigDecimal("102"),bar(0,"101","102","99","101").time(),1,false);assertThat(new IfvgDetector().invert(fvg,bar(1,"101","104","101","103"),false,false)).hasValueSatisfying(z->assertThat(z.direction()).isEqualTo(PriceZone.Direction.BULLISH));}
 @Test void ifvgDoesNotCrossContractRollover(){PriceZone fvg=new PriceZone(PriceZone.Direction.BULLISH,new BigDecimal("100"),new BigDecimal("102"),bar(0,"100","101","99","100").time(),1,false);BacktestBar rollover=new BacktestBar(bar(1,"101","102","98","99").time(),2,new BigDecimal("101"),new BigDecimal("102"),new BigDecimal("98"),new BigDecimal("99"),1);assertThat(new IfvgDetector().invert(fvg,rollover,false,false)).isEmpty();}
 @Test void displacementRequiresBodyRangeAndDirectionalClose(){var bars=List.of(bar(0,"10","11","10","10.5"),bar(1,"10","11","10","10.5"),bar(2,"10","11","10","10.5"),bar(3,"10","15","10","14.5"));assertThat(new DisplacementDetector().measure(bars,3,3,new BigDecimal("2"),new BigDecimal("2"),new BigDecimal(".7"))).hasValueSatisfying(m->assertThat(m.qualifies()).isTrue());}
}
